"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[46731],{3331:(e,i,a)=>{a.d(i,{R:()=>l,x:()=>r});var o=a(36672);const n={},t=o.createContext(n);function l(e){const i=o.useContext(t);return o.useMemo((function(){return"function"==typeof e?e(i):{...i,...e}}),[i,e])}function r(e){let i;return i=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:l(e.components),o.createElement(t.Provider,{value:i},e.children)}},44069:(e,i,a)=>{a.r(i),a.d(i,{assets:()=>s,contentTitle:()=>r,default:()=>u,frontMatter:()=>l,metadata:()=>o,toc:()=>c});const o=JSON.parse('{"id":"2023/04/07","title":"2023-04-07","description":"Se perdiamo l\'Internet Archive, siamo fottuti.","source":"@site/i18n/it/docusaurus-plugin-content-docs/current/2023/04/07.md","sourceDirName":"2023/04","slug":"/2023/04/07","permalink":"/it/2023/04/07","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/it/docusaurus-plugin-content-docs//current/2023/04/07.md","tags":[],"version":"current","frontMatter":{"localized_date":"7 aprile 2023","top_news":"Se perdiamo l\'Internet Archive, siamo fottuti."},"sidebar":"defaultSidebar","previous":{"title":"2023-04-08","permalink":"/it/2023/04/08"},"next":{"title":"2023-04-06","permalink":"/it/2023/04/06"}}');var n=a(23420),t=a(3331);const l={localized_date:"7 aprile 2023",top_news:"Se perdiamo l'Internet Archive, siamo fottuti."},r="2023-04-07",s={},c=[{value:"Se perdiamo l&#39;Internet Archive, siamo fottuti.",id:"se-perdiamo-linternet-archive-siamo-fottuti",level:2},{value:"Chrome porta la WebGPU",id:"chrome-porta-la-webgpu",level:2},{value:"Mostra Tabby - Un copilota GitHub auto-ospitato",id:"mostra-tabby---un-copilota-github-auto-ospitato",level:2},{value:"I lavoratori di Tesla hanno condiviso le immagini delle telecamere dell&#39;auto, comprese &quot;scene di intimit\xe0&quot;.",id:"i-lavoratori-di-tesla-hanno-condiviso-le-immagini-delle-telecamere-dellauto-comprese-scene-di-intimit\xe0",level:2},{value:"Spiegato semplicemente: Come funziona il GPT?",id:"spiegato-semplicemente-come-funziona-il-gpt",level:2},{value:"La progettazione di sistemi e il costo della complessit\xe0 architettonica (2013)",id:"la-progettazione-di-sistemi-e-il-costo-della-complessit\xe0-architettonica-2013",level:2},{value:"Defamed by ChatGPT",id:"defamed-by-chatgpt",level:2},{value:"Piano generale Parte 3",id:"piano-generale-parte-3",level:2},{value:"I lavoratori Tesla hanno condiviso immagini sensibili registrate dalle auto dei clienti",id:"i-lavoratori-tesla-hanno-condiviso-immagini-sensibili-registrate-dalle-auto-dei-clienti",level:2},{value:"Buck2: Il nostro sistema di compilazione open source",id:"buck2-il-nostro-sistema-di-compilazione-open-source",level:2},{value:"Mariadb.com \xe8 morto, lunga vita a MariaDB.org",id:"mariadbcom-\xe8-morto-lunga-vita-a-mariadborg",level:2},{value:"Mostra applicazione web Pomodoro ADHD-friendly",id:"mostra-applicazione-web-pomodoro-adhd-friendly",level:2},{value:"Meta rilascia a tutti un nuovo strumento di segmentazione delle foto basato sull&#39;intelligenza artificiale.",id:"meta-rilascia-a-tutti-un-nuovo-strumento-di-segmentazione-delle-foto-basato-sullintelligenza-artificiale",level:2},{value:"Cosa succede quando si perdono le credenziali AWS e come AWS minimizza il danno",id:"cosa-succede-quando-si-perdono-le-credenziali-aws-e-come-aws-minimizza-il-danno",level:2},{value:"Gource - Animare la cronologia Git",id:"gource---animare-la-cronologia-git",level:2},{value:"Mostra Genera idee di startup basate sui commenti di Discussion Service",id:"mostra-genera-idee-di-startup-basate-sui-commenti-di-discussion-service",level:2},{value:"DevOps utilizza un modello di capacit\xe0, non un modello di maturit\xe0.",id:"devops-utilizza-un-modello-di-capacit\xe0-non-un-modello-di-maturit\xe0",level:2},{value:"Aggiungere capacit\xe0 alla rete elettrica non \xe8 un compito semplice.",id:"aggiungere-capacit\xe0-alla-rete-elettrica-non-\xe8-un-compito-semplice",level:2},{value:"Annuncio di WCGI: WebAssembly e CGI",id:"annuncio-di-wcgi-webassembly-e-cgi",level:2},{value:"JSON vs. XML",id:"json-vs-xml",level:2},{value:"Sito web ospitato su un server Linux di 24 anni fa.",id:"sito-web-ospitato-su-un-server-linux-di-24-anni-fa",level:2},{value:"\xc8 colpa mia se non riesci a gestire la verit\xe0? (2019)",id:"\xe8-colpa-mia-se-non-riesci-a-gestire-la-verit\xe0-2019",level:2},{value:"Corde C e la mia lenta discesa verso la follia",id:"corde-c-e-la-mia-lenta-discesa-verso-la-follia",level:2},{value:"MutexProtected: Un modello C++ per una concorrenza pi\xf9 semplice",id:"mutexprotected-un-modello-c-per-una-concorrenza-pi\xf9-semplice",level:2},{value:"Clarence Thomas e il miliardario",id:"clarence-thomas-e-il-miliardario",level:2},{value:"La scarsa componibilit\xe0 di Rust",id:"la-scarsa-componibilit\xe0-di-rust",level:2},{value:"Individuare ed evitare la frammentazione dell&#39;heap nelle applicazioni Rust",id:"individuare-ed-evitare-la-frammentazione-dellheap-nelle-applicazioni-rust",level:2},{value:"Fate attenzione a ci\xf2 che testate o distribuite su Vercel.",id:"fate-attenzione-a-ci\xf2-che-testate-o-distribuite-su-vercel",level:2},{value:"Linux 6.4 porta le aggiunte di Apple M2 per i MacBook e i Mac Mini 2022",id:"linux-64-porta-le-aggiunte-di-apple-m2-per-i-macbook-e-i-mac-mini-2022",level:2},{value:"Illustrazioni di treni di manutenzione giapponesi &quot;invisibili&quot; che funzionano solo di notte",id:"illustrazioni-di-treni-di-manutenzione-giapponesi-invisibili-che-funzionano-solo-di-notte",level:2}];function d(e){const i={a:"a",code:"code",h1:"h1",h2:"h2",header:"header",p:"p",...(0,t.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(i.header,{children:(0,n.jsx)(i.h1,{id:"2023-04-07",children:"2023-04-07"})}),"\n",(0,n.jsx)(i.h2,{id:"se-perdiamo-linternet-archive-siamo-fottuti",children:"Se perdiamo l'Internet Archive, siamo fottuti."}),"\n",(0,n.jsxs)(i.p,{children:["(",(0,n.jsx)(i.a,{href:"https://www.sbstatesman.com/2023/04/04/if-we-lose-the-internet-archive-were-screwed/",children:"https://www.sbstatesman.com/2023/04/04/if-we-lose-the-internet-archive-were-screwed/"}),").\nL'Internet Archive, che si descrive come \"una biblioteca senza scopo di lucro di milioni di libri, film, software, musica, siti web e altro ancora\", \xe8 stato citato in giudizio da quattro case editrici per aver violato il diritto d'autore e un giudice federale si \xe8 pronunciato a favore delle case editrici. Tuttavia, Internet Archive sta facendo ricorso contro la decisione, che secondo alcuni \xe8 fondamentalmente un attacco contro i servizi pubblici finanziati dai contribuenti da parte di aziende e privati. I critici sostengono che la chiusura della National Emergency Library, che ha reso disponibili gratuitamente i libri protetti da copyright durante la pandemia COVID-19, \xe8 molto pi\xf9 disastrosa per la classe operaia di quanto possa esserlo l'accesso ai libri. Se l'appello non avr\xe0 successo, gli esseri umani perderanno pi\xf9 conoscenza di quanta ne abbia mai contenuta la Biblioteca di Alexandra."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35468753",children:"Discussion Service"}),".\nGli utenti di Discussion Service discutono le leggi sul copyright e la conservazione culturale. Le battaglie legali sollevano questioni sulla legittimit\xe0 del copyright e sui monopoli governativi. Alcuni chiedono una migliore governance per incoraggiare il lavoro e termini di copyright pi\xf9 brevi. La perdita dell'AI potrebbe riscrivere la storia, evidenziando l'importanza della conservazione della conoscenza. Si suggerisce di creare un nuovo ente o di interrompere le donazioni a causa del comportamento rischioso dell'AI. La Biblioteca nazionale di emergenza \xe8 vista come inaspettata e benefica, ma i leader dell'AI hanno la responsabilit\xe0 di preservare la storia."]}),"\n",(0,n.jsx)(i.h2,{id:"chrome-porta-la-webgpu",children:"Chrome porta la WebGPU"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://developer.chrome.com/blog/webgpu-release/",children:"Originale"}),".\nChrome lancia WebGPU, una nuova API per la grafica web che offre grafica 3D migliorata e calcolo in parallelo dei dati su ChromeOS, macOS e Windows, per fornire l'accesso alle capacit\xe0 avanzate delle GPU e una programmazione efficiente con la piattaforma web. WebGPU \xe8 stata progettata con un'API JavaScript idiomatica, l'integrazione con le promesse e ottimi messaggi di errore, ed \xe8 una base per futuri miglioramenti, come l'accesso agli shader core per ulteriori ottimizzazioni di machine learning e una maggiore ergonomia in WGSL. WebGPU \xe8 il risultato di un lavoro di collaborazione durato 6 anni da parte del gruppo comunitario \"GPU for the Web\" del W3C, con il contributo di Mozilla, Apple, Intel e Microsoft. Le piattaforme ChromeOS, Windows e macOS possono supportare WebGPU, mentre Linux, Android e altre piattaforme estenderanno il supporto nel prossimo futuro. Le librerie WebGL pi\xf9 diffuse, come Babylon.js, PlayCanvas e TensorFlow.js, offrono gi\xe0 un supporto WebGPU o ci stanno lavorando. Le risorse per saperne di pi\xf9 su WebGPU includono le specifiche W3C, la documentazione MDN, i campioni, il GPU Compute e altri ancora."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35465729",children:"Discussion Service"}),".\nChrome ha distribuito WebGPU, che promette miglioramenti rispetto a WebGL. WebGPU \xe8 una novit\xe0 con contributi positivi; le opinioni variano sulla priorit\xe0 da dare alle GPU desktop o mobili. Gli utenti discutono dei modi per limitare le funzionalit\xe0 del browser che perdono informazioni e per prevenire il fingerprinting. Ci sono preoccupazioni per il potenziale uso dannoso per il mining di criptovalute. Il sondaggio Web3DS rileva le caratteristiche e i limiti relativi alle WebGPU. C'\xe8 entusiasmo per la potenziale adozione di WebGPU, nonostante le preoccupazioni per le limitazioni rispetto a tecnologie grafiche pi\xf9 capaci."]}),"\n",(0,n.jsx)(i.h2,{id:"mostra-tabby---un-copilota-github-auto-ospitato",children:"Mostra Tabby - Un copilota GitHub auto-ospitato"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://github.com/TabbyML/tabby",children:"Originale"}),".\nTabbyML ha rilasciato Tabby, un'alternativa self-hosted a GitHub Copilot che \xe8 open-source e on-prem. Si caratterizza per l'autocontenimento, senza bisogno di DBMS o servizi cloud, un'interfaccia web per la visualizzazione e la configurazione di modelli e MLOP, un'interfaccia OpenAPI e una facile integrazione con l'infrastruttura esistente. Gli sviluppatori possono utilizzare l'immagine docker per semplificare la distribuzione e TabbyML supporta GPU di livello consumer con caricamento del peso FP-16 e altre ottimizzazioni. Il server FastAPI incorpora una documentazione OpenAPI dell'API HTTP."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35470915",children:"Discussion Service"}),".\nTabby, un'alternativa a GitHub Copilot, offre un controllo completo sui dati e sulla privacy durante la messa a punto dei modelli. Risparmia tempo ma solleva problemi di privacy. I problemi di privacy di GitHub sono esagerati e Copilot ha dei limiti. TabbyML genera codice boilerplate e solleva dubbi sulla salvaguardia della propriet\xe0 intellettuale del codice. La versione Alpha di Tabby \xe8 popolare nonostante la mancanza di una vetrina professionale e di prove a supporto. Copilot prevede il codice in modo accurato, ma ha dei limiti e pu\xf2 suggerire codice scadente. Alcuni utenti suggeriscono una versione self-hosted di Copilot e un cambio di nome per migliorare il SEO."]}),"\n",(0,n.jsx)(i.h2,{id:"i-lavoratori-di-tesla-hanno-condiviso-le-immagini-delle-telecamere-dellauto-comprese-scene-di-intimit\xe0",children:'I lavoratori di Tesla hanno condiviso le immagini delle telecamere dell\'auto, comprese "scene di intimit\xe0".'}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://arstechnica.com/tech-policy/2023/04/tesla-workers-shared-images-from-car-cameras-including-scenes-of-intimacy/",children:"Originale"}),'.\nSecondo quanto riferito, i dipendenti Tesla hanno condiviso video e immagini riprese dalle telecamere delle auto dei clienti attraverso un sistema di messaggistica interna, che includeva contenuti "talvolta altamente invasivi". Nonostante Tesla sostenga che le telecamere di bordo siano "progettate da zero per proteggere la privacy", i dipendenti avevano facile accesso ai risultati delle telecamere e condividevano "liberamente" i contenuti. Tra gli elementi condivisi vi erano scene intime che non presentavano nudit\xe0, oltre ad "alcuni capi di biancheria e alcuni articoli per il benessere sessuale". Tuttavia, alcuni ex-lavoratori hanno affermato che la condivisione era legittima per motivi di lavoro. In alternativa, alcune immagini sarebbero state ampiamente condivise e viste anche dalla dirigenza.']}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35471826",children:"Discussion Service"}),".\nGli utenti discutono di articoli duplicati e delle linee guida del sito per l'invio di fonti originali. Nessun commento pertinente sull'argomento della condivisione da parte di Tesla delle immagini delle telecamere delle auto, comprese le \"scene di intimit\xe0\"."]}),"\n",(0,n.jsx)(i.h2,{id:"spiegato-semplicemente-come-funziona-il-gpt",children:"Spiegato semplicemente: Come funziona il GPT?"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://confusedbit.dev/posts/how_does_gpt_work/",children:"Originale"}),".\nL'articolo illustra il processo che sta alla base del GPT-3 e come viene utilizzato per le conversazioni in linguaggio naturale attraverso l'incorporazione di parole e modelli probabilistici. I suoi punti di forza sono la generazione di testo e il collegamento logico delle idee, ma incontra dei limiti con le false informazioni e le restrizioni di input. Esistono somiglianze e differenze con la struttura del cervello umano, tra cui le capacit\xe0 linguistiche limitate del GPT e la mancanza di apprendimento continuo. L'articolo solleva anche questioni di coscienza e preoccupazioni per la perdita di posti di lavoro, ma osserva che la GPT da sola non pu\xf2 nuocere. Tuttavia, l'ulteriore sviluppo dell'IA richiede cautela e gli esperti ricercano modi per prevenire gli esiti negativi. Le competenze tecniche e lo spirito imprenditoriale saranno preziosi, poich\xe9 le conseguenze della GPT rimangono ancora incerte."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35466201",children:"Discussion Service"}),".\nGli esperti di Hacker News discutono le capacit\xe0 e i limiti dei modelli linguistici dell'intelligenza artificiale, tra cui ChatGPT e GPT-4. Alcuni sono cauti nell'attribuire alle macchine propriet\xe0 simili a quelle umane, ma ChatGPT produce testo accurato e specifico per il contesto, una componente dell'intelligenza artificiale. Dibattito sulla rilevanza dello scenario della stanza cinese e sulla natura dell'intelligenza e della coscienza. Attenzione alle capacit\xe0 pratiche e all'innovazione, alla rilevanza dei trasformatori e ai limiti dei dati di addestramento. Gli scettici notano che il GPT-4 manca dei meccanismi di feedback dei cervelli biologici, pur generando testi simili a quelli umani."]}),"\n",(0,n.jsx)(i.h2,{id:"la-progettazione-di-sistemi-e-il-costo-della-complessit\xe0-architettonica-2013",children:"La progettazione di sistemi e il costo della complessit\xe0 architettonica (2013)"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://dspace.mit.edu/handle/1721.1/79551",children:"Originale"}),".\nIl messaggio di errore ",(0,n.jsx)(i.code,{children:"HTTP Status 429 - Too Many Requests"})," indica che l'utente ha inviato un elevato volume di richieste in breve tempo."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35470905",children:"Discussion Service"}),".\nL'articolo discute la progettazione del sistema e il costo della complessit\xe0 architettonica. Gli utenti condividono le loro esperienze personali con i fornitori di cloud e la comprensione di sistemi complessi. I commenti sottolineano l'importanza della semplicit\xe0, di una buona documentazione e di pensare al futuro. I vantaggi e le sfide dell'architettura del software e il bilanciamento tra semplicit\xe0 e complessit\xe0 sono discussi dagli esperti. Si discute anche della definizione di complessit\xe0 nei sistemi software."]}),"\n",(0,n.jsx)(i.h2,{id:"defamed-by-chatgpt",children:"Defamed by ChatGPT"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://jonathanturley.org/2023/04/06/defamed-by-chatgpt-my-own-bizarre-experience-with-artificiality-of-artificial-intelligence/",children:"Originale"}),".\nN/A."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35468540",children:"Discussion Service"}),".\nLa diffamazione generata dall'intelligenza artificiale rappresenta un rischio significativo e ChatGPT \xe8 sotto esame per la sua potenziale responsabilit\xe0. Gli utenti discutono la responsabilit\xe0 per i suoi risultati e suggeriscono di mantenere uno standard di cura. Vengono discussi anche i problemi di responsabilit\xe0 delle auto autonome e le implicazioni legali di ChatGPT come strumento di consulenza medica e legale. Sono state sollevate anche preoccupazioni sull'accuratezza dei modelli linguistici e sull'uso etico dei dati personali. Sono state avanzate critiche sull'affidabilit\xe0 di ChatGPT e sulla propagazione della disinformazione, che hanno portato alla richiesta di dichiarazioni di non responsabilit\xe0 e di accordi vincolanti sui termini di servizio. L'intersezione tra tecnologia e societ\xe0 \xe8 uno dei temi principali di questo post, con dibattiti legali in corso sulla responsabilit\xe0 dei risultati generati dall'IA."]}),"\n",(0,n.jsx)(i.h2,{id:"piano-generale-parte-3",children:"Piano generale Parte 3"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://www.tesla.com/blog/master-plan-part-3",children:"Originale"}),".\nTesla pubblica la Parte 3 del Master Plan, proponendo un percorso verso un'economia energetica globale sostenibile attraverso l'elettrificazione, la generazione e l'immagazzinamento dell'elettricit\xe0, con ipotesi, fonti e calcoli dettagliati alla base della proposta. I lettori sono invitati a fornire contributi e a partecipare alla conversazione. Tesla fornisce anche il profilo di domanda degli Stati Uniti completamente elettrificati utilizzato nella modellazione."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35462378",children:"Discussion Service"}),".\nIl Master Plan di Tesla Parte 3 riceve attenzione su Hacker News con discussioni sulla vita senza combustibili fossili, la fattibilit\xe0 dei veicoli elettrici, gli investimenti nelle energie rinnovabili e la diffusione del COVID-19. Gli utenti discutono sulla praticabilit\xe0 della transizione alle energie rinnovabili, sull'onere finanziario delle tasse per i super ricchi e sulla strumentalizzazione della gentilezza e della tolleranza in politica. Si discute anche della reputazione di Tesla, del trattamento dei dipendenti e della visione del futuro. L'editore deve identificare il messaggio principale ed evitare pregiudizi politici o religiosi."]}),"\n",(0,n.jsx)(i.h2,{id:"i-lavoratori-tesla-hanno-condiviso-immagini-sensibili-registrate-dalle-auto-dei-clienti",children:"I lavoratori Tesla hanno condiviso immagini sensibili registrate dalle auto dei clienti"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://www.reuters.com/technology/tesla-workers-shared-sensitive-images-recorded-by-customer-cars-2023-04-06/",children:"Originale"}),".\nI dipendenti Tesla hanno condiviso video sensibili catturati dalle telecamere delle auto dei clienti tra il 2019 e il 2022, secondo le interviste di Reuters a nove ex lavoratori Tesla. Tra i video condivisi attraverso il sistema di messaggistica interna di Tesla, alcuni dei quali pubblicamente, figurano incidenti, violenze stradali e situazioni imbarazzanti. La nota sulla privacy dei clienti dell'azienda sottolinea la garanzia di anonimato delle registrazioni delle telecamere che non sono collegate ai clienti o ai loro veicoli, ma alcuni ex dipendenti l'hanno definita una \"violazione della privacy\". Tesla ha risposto alle preoccupazioni sulla protezione dei dati apportando modifiche alla modalit\xe0 Sentry, tra cui l'accensione dei fari delle auto parcheggiate per avvisare i passanti che potrebbero essere monitorati. Reuters sostiene che tutte le citazioni saranno ritardate e fornisce i link per le correzioni e il feedback del sito."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35468855",children:"Discussion Service"}),".\nI lavoratori di Tesla hanno condiviso immagini sensibili registrate dalle auto dei clienti senza salvaguardare la privacy. Le norme sulla privacy con gravi conseguenze devono essere applicate e le aziende devono costruire la privacy dalle fondamenta. Gli aneddoti evidenziano la mancanza di privacy in diverse aziende e startup, mentre in India si critica la mancanza di leggi sulla privacy digitale. La privacy dei dati non \xe8 del tutto sicura e i dipendenti possono vedere i dati privati e farne un uso improprio. Gli standard tedeschi sulla privacy non sono perfetti, ma le autorit\xe0 per la protezione dei dati sarebbero interessate a eventuali violazioni dei dati da parte delle case automobilistiche a causa dell'applicazione del GDPR. I veicoli connessi destano preoccupazioni in termini di privacy, ma alcuni fanno notare che capacit\xe0 di tracciamento simili esistono anche nei veicoli non elettrici. Secondo alcuni rapporti, alcuni istituti di credito hanno installato dispositivi di tracciamento sulle auto, anche se non \xe8 chiaro se vendano i dati."]}),"\n",(0,n.jsx)(i.h2,{id:"buck2-il-nostro-sistema-di-compilazione-open-source",children:"Buck2: Il nostro sistema di compilazione open source"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://engineering.fb.com/2023/04/06/open-source/buck2-open-source-large-scale-build-system/",children:"Originale"}),".\nMeta rilascia Buck2, un sistema di compilazione open source su GitHub, scritto in Rust. Buck2 separa le regole fondamentali da quelle specifiche per le lingue, con test interni che indicano build due volte pi\xf9 veloci di Buck1, un maggiore parallelismo e un output della console ridisegnato. Buck2 potrebbe essere adatto a progetti multilingue di dimensioni moderate, progettato con funzioni avanzate per le prestazioni e funzioni di dipendenza dinamiche ed espressive. Meta condivide progetti tecnologici open source, tra cui AI, dati, sviluppo, front-end, linguaggi, piattaforme, sicurezza e VR, senza che siano stati menzionati aggiornamenti o rilasci degni di nota."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35470371",children:"Discussion Service"}),".\nIl sistema di compilazione open-source Buck2 di Facebook guadagna attenzione per il suo motore di calcolo incrementale e il supporto per Windows. Gli utenti di Discussion Service discutono di altri strumenti di compilazione, tra cui Waf, TensorFlow e Py_wheel, evidenziando le sfide legate alla gestione di grandi basi di codice. Buck2 elimina la dipendenza dalla JVM di Buck1 riscrivendolo in Rust. Buck2 e Bazel sono sistemi di compilazione multilingue con build riproducibili e funzionalit\xe0 di integrazione. L'articolo suggerisce di usare lo strumento giusto per il lavoro giusto e di concentrarsi sui punti di forza di uno strumento. Alcuni utenti sostengono che la compilazione statica aggiunge complessit\xe0, mentre altri sostengono i vantaggi dei binari collegati staticamente."]}),"\n",(0,n.jsx)(i.h2,{id:"mariadbcom-\xe8-morto-lunga-vita-a-mariadborg",children:"Mariadb.com \xe8 morto, lunga vita a MariaDB.org"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://medium.com/@imashadowphantom/mariadb-com-%C3%A8-morto-lungo-vive-mariadb-org-b8a0ca50a637",children:"Originale"}),".\nMariaDB.com, l'entit\xe0 commerciale, sta affrontando fallimenti dovuti a scarsa leadership, razzismo, sessismo e violazioni delle leggi sul lavoro. Monty, il fondatore, \xe8 stato rimosso dal consiglio di amministrazione nel luglio 2022 e l'acquisizione ostile da parte dell'amministratore delegato Michael Howard ha portato a un calo del valore delle azioni. I documenti della SEC indicano che MariaDB potrebbe chiudere, dovendo affrontare problemi di mantenimento e assunzione del personale a causa della sua reputazione. Ai dipendenti viene consigliato di programmare colloqui con altre aziende, pur elogiando MariaDB.org e l'open source."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35467243",children:"Discussion Service"}),".\nLa chiusura di MariaDB.com fa sorgere il sospetto di instabilit\xe0 finanziaria. Le accuse di parzialit\xe0 e di infondatezza rivolte a MariaDB Corp. sono accolte con scetticismo. L'opinione pubblica \xe8 divisa sul futuro di MariaDB.org. Il thread di Hacker News discute le accuse di discriminazione e si sposta sul confronto tra MariaDB e Postgres. MariaDB Corporation dichiara bancarotta, l'impatto sullo sviluppo \xe8 incerto. Le azioni di MariaDB PLC calano di quasi il 70% dall'IPO, gli analisti sono preoccupati per il management inesperto e i cambiamenti nel settore. La perdita di 20 milioni di dollari in una causa legale e la fusione con SkySQL contribuiscono ai problemi finanziari. Le preoccupazioni per lo sviluppo futuro sono infondate grazie agli sponsor aziendali."]}),"\n",(0,n.jsx)(i.h2,{id:"mostra-applicazione-web-pomodoro-adhd-friendly",children:"Mostra applicazione web Pomodoro ADHD-friendly"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://brainpls.work/",children:"Originale"}),".\nPurtroppo, trattandosi di un commento di una sola riga, non ci sono informazioni sufficienti per fornire un riassunto conciso."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35471129",children:"Discussion Service"}),".\nIl timer basato sul Pomodoro di Brainpls.work per il supporto all'ADHD \xe8 stato criticato in quanto basato sul web. Sono stati avanzati suggerimenti per migliorare il dispositivo del timer e l'applicazione del browser. Nuova applicazione per il timer dell'attenzione e del flusso rilasciata su Github, preferita come applicazione nativa. Gli utenti apprezzano l'applicazione di flashcard personali per il monitoraggio dei progressi. Il feedback include l'aggiunta di notifiche sonore, la marcatura delle distrazioni e la visualizzazione dell'ora locale. Lo sviluppatore dell'app potrebbe essere affetto da ADHD."]}),"\n",(0,n.jsx)(i.h2,{id:"meta-rilascia-a-tutti-un-nuovo-strumento-di-segmentazione-delle-foto-basato-sullintelligenza-artificiale",children:"Meta rilascia a tutti un nuovo strumento di segmentazione delle foto basato sull'intelligenza artificiale."}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://arstechnica.com/information-technology/2023/04/meta-introduces-ai-model-that-can-isolate-and-mask-objects-within-images/",children:"Originale"}),".\nMeta ha sviluppato un nuovo modello di segmentazione delle immagini, chiamato SAM, in grado di isolare a comando qualsiasi oggetto in immagini o video. SAM mira a democratizzare il processo di segmentazione delle immagini, riducendo la necessit\xe0 di formazione e competenze specialistiche. La tecnologia \xe8 adatta alla comprensione dei contenuti delle pagine web, all'editing delle immagini e alle applicazioni di realt\xe0 aumentata. SAM si distingue per la sua capacit\xe0 di identificare oggetti non presenti nel set di dati di addestramento e per il suo approccio parzialmente aperto. Inoltre, Meta ha creato un set di dati chiamato SA-1B, che comprende 11 milioni di immagini e 1,1 miliardi di maschere di segmentazione, che sar\xe0 reso disponibile per scopi di ricerca con una licenza Apache 2.0."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35468304",children:"Discussion Service"}),".\nMeta rilascia uno strumento di segmentazione delle foto basato sull'intelligenza artificiale, lodando l'apertura e lo sviluppo dell'intelligenza artificiale. Alcuni si preoccupano della fattibilit\xe0 della piattaforma. Modello addestrato su 12,6 milioni di immagini open-source. Gli utenti criticano il titolo fuorviante dell'articolo e gli strumenti di segmentazione esistenti. Nessuna rilevanza per l'estensione di Chrome o le applicazioni YC."]}),"\n",(0,n.jsx)(i.h2,{id:"cosa-succede-quando-si-perdono-le-credenziali-aws-e-come-aws-minimizza-il-danno",children:"Cosa succede quando si perdono le credenziali AWS e come AWS minimizza il danno"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://xebia.com/blog/what-happens-when-you-leak-aws-credentials-and-how-aws-minimizes-the-damage/",children:"Originale"}),".\nUn utente AWS ha fatto trapelare intenzionalmente le proprie credenziali AWS in un repository GitHub pubblico per vedere cosa sarebbe successo. Entro un minuto dalla divulgazione delle credenziali, AWS ha aggiunto un \"criterio di quarantena\" all'account dell'utente e lo ha informato via e-mail con istruzioni su come proteggere il suo account. Un attore malintenzionato ha rapidamente effettuato chiamate API automatiche con le credenziali trapelate, ma senza successo a causa delle autorizzazioni limitate. AWS utilizza un servizio di GitHub Secrets Scanning per rilevare e rispondere rapidamente alle fughe di credenziali. Per prevenire la fuga di credenziali, gli utenti possono eseguire scansioni pre-commit a livello locale o aggiungere un secret scanner alla loro pipeline CI/CD."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35466675",children:"Discussion Service"}),".\nUn utente di Discussion Service ha impostato un progetto per far trapelare automaticamente i segreti AWS e attivare processi di scansione. \xc8 frustrante ruotare le chiavi con molti account. AWS invalida i token nei repository pubblici, ma i ladri potrebbero gi\xe0 avere accesso. Si consiglia agli utenti AWS di parlare con il team prima di revocare le chiavi in produzione. L'assistenza AWS deve essere contattata il prima possibile dopo un attacco. \xc8 possibile aggiungere ulteriore sicurezza limitando l'uso delle chiavi a determinati IP. Uno script o un hook git possono impedire il push delle credenziali. L'intento di programmazione di Scanner non \xe8 chiaro."]}),"\n",(0,n.jsx)(i.h2,{id:"gource---animare-la-cronologia-git",children:"Gource - Animare la cronologia Git"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://gource.io/",children:"Originale"}),".\nGource \xe8 un generatore di grafici ad albero animati per le directory dei progetti software su cui gli sviluppatori possono lavorare. Lo strumento ha un supporto integrato per i log di Git, Mercurial, Bazaar e SVN e pu\xf2 analizzare i log creati da strumenti di terze parti per i repository CVS. Gource dispone di un'ampia documentazione, esempi e controlli sulla sua pagina wiki, che includono nuove funzioni, font, filtri e opzioni come l'opzione --high-dpi, --file-idle-time-at-end o --fixed-user-size. Gource 0.54 \xe8 l'ultima versione, che include il supporto sperimentale per Wayland e la correzione di bug su Apple M1. Esistono altri strumenti simili, come Logstalgia, considerato un utile strumento di visualizzazione dei log di accesso ai server web. Se vi piace Gource, potete mostrare il vostro apprezzamento e fare una donazione al suo autore per incoraggiare lo sviluppo futuro di questo e di altri progetti open-source."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35471420",children:"Discussion Service"}),".\nGource, uno strumento per animare la cronologia di Git, \xe8 apprezzato per determinare la struttura del progetto, le tendenze di modifica e i modelli di lavoro, ed \xe8 spesso usato per una visualizzazione divertente. Gli utenti di Reddit condividono l'uso di questo strumento per visualizzare l'attivit\xe0 dei commenti e le modifiche al codice. Alcune aziende lo mostrano anche pubblicamente. Alcuni faticano a trovare usi pratici, ma lo trovano gratificante come strumento di riflessione. Per molti \xe8 esteticamente piacevole."]}),"\n",(0,n.jsx)(i.h2,{id:"mostra-genera-idee-di-startup-basate-sui-commenti-di-discussion-service",children:"Mostra Genera idee di startup basate sui commenti di Discussion Service"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://hn-ideas.tjcx.me/",children:"Originale"}),".\nPresentiamo un nuovo strumento online che genera idee di startup sulla base di argomenti tratti dai commenti pubblicati su Hacker News. Sviluppata da un individuo di nome tjcx, la piattaforma consente agli utenti di inserire un argomento e di ricevere un'idea di startup casuale basata sui commenti relativi a quell'argomento. Questa invenzione pu\xf2 rivelarsi utile per dare potere agli imprenditori e promuovere l'innovazione."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35467917",children:"Discussion Service"}),".\n\xc8 stato creato un nuovo generatore di idee di startup utilizzando i commenti di Discussion Service. Le idee vanno dal serio al sarcastico, tra cui un servizio di abbonamento al sangue di capra e l'assunzione di sicari. I commenti prendono in giro le idee, ma suggeriscono anche piattaforme per l'UBI e la medicina personalizzata. Altri suggerimenti includono app per il fitness, dispositivi per il monitoraggio della temperatura e VR per il monitoraggio degli animali domestici. Gli utenti di Discussion Service propongono un'ampia gamma di idee di startup, comprese quelle controverse come le bambole sessuali per bambini e la carne umana cresciuta in laboratorio. I risultati riportati sono contrastanti: alcuni li trovano divertenti, altri poco utili. L'accuratezza \xe8 criticata e i commenti politici o religiosi sono scoraggiati."]}),"\n",(0,n.jsx)(i.h2,{id:"devops-utilizza-un-modello-di-capacit\xe0-non-un-modello-di-maturit\xe0",children:"DevOps utilizza un modello di capacit\xe0, non un modello di maturit\xe0."}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://octopus.com/blog/devops-uses-capability-not-maturity",children:"Originale"}),".\nSecondo Steve Fenton, DevOps dovrebbe utilizzare un modello di capacit\xe0, non un modello di maturit\xe0. A differenza di un modello di maturit\xe0, l'approccio \xe8 basato sui risultati e incoraggia la sperimentazione di strumenti e processi. Basato su SEM, personalizzabile e dinamico, \xe8 in grado di guidare i guadagni incrementali identificando le capacit\xe0. I modelli di maturit\xe0 possono essere rigidi, standardizzati e non considerare le sfide aziendali uniche. Il modello delle capacit\xe0 collega le caratteristiche a risultati pi\xf9 ampi del sistema. Il modello strutturale \xe8 eccessivo, ma deve essere utilizzato per il miglioramento continuo."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35466718",children:"Discussion Service"}),'.\nDevOps ha trasformato i ruoli dei team di sviluppo e ha spinto i livelli di competenza dei SysAdmin ad aumentare. Alcuni suggeriscono termini alternativi come "ingegneria della piattaforma". Il modello di capacit\xe0 basato sulle metriche \xe8 stato criticato come un\'operazione di vendita, ma si chiede che le capacit\xe0 siano significative. Coltivare la cultura del provare cose nuove per lo sviluppo del business.']}),"\n",(0,n.jsx)(i.h2,{id:"aggiungere-capacit\xe0-alla-rete-elettrica-non-\xe8-un-compito-semplice",children:"Aggiungere capacit\xe0 alla rete elettrica non \xe8 un compito semplice."}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://www.economist.com/technology-quarterly/2023/04/05/adding-capacity-to-the-electricity-grid-is-not-a-simple-task",children:"Originale"}),".\nLa rete elettrica deve affrontare sfide per l'integrazione delle fonti rinnovabili, con pochi fornitori disposti a espandere la capacit\xe0 dei trasformatori. Una regolamentazione conservativa e connessioni alla rete insufficienti limitano la quota di mercato delle rinnovabili, causando ritardi e incertezze nei nuovi progetti. Le autorit\xe0 di regolamentazione riconoscono la necessit\xe0 di connessioni a lungo termine per la decarbonizzazione della rete, con nuove norme a sostegno dei progetti di energia rinnovabile. L'India prevede di collegare 500 GW di capacit\xe0 rinnovabile entro il 2030, mentre la Cina beneficia della recente espansione della rete. Tuttavia, l'ottimizzazione della gestione delle code e delle procedure di pianificazione rimane cruciale, poich\xe9 la costruzione di infrastrutture di rete deve bilanciare equilibri delicati."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35463182",children:"Discussion Service"}),".\nL'aggiunta di capacit\xe0 alla rete elettrica deve affrontare problemi di permessi, leggi ambientali, propriet\xe0, esproprio e ricerca di proprietari non registrati. I Paesi devono affrontare problemi di rete unici, come la rete elettrica trascurata del Sudafrica e la capacit\xe0 di rete dei Paesi Bassi che non riesce a tenere il passo con gli investimenti. Nel Regno Unito le vecchie infrastrutture di rete vengono riutilizzate per nuovi parchi eolici off-shore, ma molti progetti verdi hanno date di scadenza fissate al 2030. Si discute della stabilit\xe0 della rete rispetto alla promozione delle fonti di energia rinnovabili e della necessit\xe0 dell'idrogeno per lo stoccaggio dell'energia. Le sfide delle fonti rinnovabili includono la sovracostruzione, lo stoccaggio e la connettivit\xe0 della rete. I sudafricani hanno meno interruzioni di corrente rispetto a Paesi come Germania e Austria. La Cina \xe8 leader nella trasmissione a corrente continua ad altissima tensione. Le fonti rinnovabili non hanno mai rappresentato un problema per le reti, anche se l'inerzia sintetica e la gestione di improvvisi cali di fornitura rimangono una sfida."]}),"\n",(0,n.jsx)(i.h2,{id:"annuncio-di-wcgi-webassembly-e-cgi",children:"Annuncio di WCGI: WebAssembly e CGI"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://wasmer.io/posts/announcing-wcgi",children:"Originale"}),".\nWasmer ha presentato WCGI, una tecnologia che combina la potenza di WebAssembly con la semplicit\xe0 di CGI per lo sviluppo lato server. \xc8 in grado di riutilizzare le applicazioni CGI esistenti, di creare pacchetti di dimensioni ridottissime con solo logica aziendale e risorse statiche e di eseguire il codice WebAssembly in una sandbox. Garantisce maggiore efficienza, sicurezza e flessibilit\xe0 nello sviluppo lato server e ha il potenziale per rimodellare il panorama delle applicazioni serverless. Gli sviluppatori web possono creare applicazioni WCGI con Rust e PHP compilandole in Wasm e i server WCGI possono essere eseguiti utilizzando la CLI di Wasmer. Wasmer lavora continuamente per espandere le possibilit\xe0 di WCGI."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35469276",children:"Discussion Service"}),".\nWasmer.io annuncia WCGI, che consente una perfetta integrazione con i server esistenti; Java Servlets contro gli standard aperti; soluzioni WebAssembly al di fuori del browser. Si discute di applet Java, GWT e JVM. WCGI offre isolamento della memoria, capacit\xe0 di output CGI ed elimina la necessit\xe0 di variabili d'ambiente. Test delle prestazioni di Wordpress su WCGI. Gli sviluppatori utilizzano WASM e Wasmer per l'inclusione di codice nativo, riducendo i ritardi e migliorando la portabilit\xe0. Allocazione delle risorse delle app ad alta sicurezza e controllo dei moduli. Velocit\xe0 di esecuzione pi\xf9 bassa su WebAssembly rispetto al nativo."]}),"\n",(0,n.jsx)(i.h2,{id:"json-vs-xml",children:"JSON vs. XML"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://corecursive.com/json-vs-xml-douglas-crockford/#",children:"Originale"}),".\nDoug Crockford, creatore di JSON, condivide la sua storia nel podcast CoRecursive e parla delle sue battaglie contro XML, della storia di JavaScript e del suo ruolo nel rendere JSON uno standard. Riflette inoltre sulla sua carriera e incoraggia gli sviluppatori ad abbracciare nuovi paradigmi. Gli utenti di Discussion Service condividono le loro esperienze e i loro pensieri su vari argomenti tecnologici. Nel complesso, questi post offrono spunti preziosi per i professionisti che desiderano ampliare le proprie conoscenze."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35467711",children:"Discussion Service"}),".\nGli esperti discutono i pro e i contro di XML e JSON: alcuni preferiscono XML per i dati complessi, mentre altri suggeriscono JSON per la sua semplicit\xe0 e l'adozione diffusa. Douglas Crockford \xe8 venerato dai programmatori e occupa un posto speciale nel cuore degli appassionati di JS. Gli utenti discutono dei vantaggi e degli svantaggi dei diversi formati di dati e linguaggi di programmazione, senza che vi sia una soluzione chiara ai loro intrinseci compromessi. Nonostante il dibattito, i diversi formati esistono per un motivo e dovrebbero essere scelti in base alle esigenze del momento. Adam Bosworth sostiene che la diffusione esplosiva dell'HTML \xe8 dovuta ai suoi limiti, non a dispetto di essi, e che l'XML \xe8 troppo complesso per gli utenti comuni."]}),"\n",(0,n.jsx)(i.h2,{id:"sito-web-ospitato-su-un-server-linux-di-24-anni-fa",children:"Sito web ospitato su un server Linux di 24 anni fa."}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://raq.serialport.org/",children:"Originale"}),".\nPoich\xe9 non \xe8 stato fornito alcun contenuto testuale, non sono in grado di fornire un riassunto per questo compito."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35468637",children:"Discussion Service"}),".\nUn server Linux di 24 anni fa \xe8 ancora in funzione con NetBSD e Apache e ospita un sito web. Gli utenti ricordano la tecnologia web obsoleta e alcuni suggeriscono nuovi modi per implementare i guest book o i contatori di visite. Si discute anche dell'accesso concorrente ai file e dell'atteggiamento della societ\xe0 nei confronti della programmazione. Ospitare un sito web su un hardware obsoleto non \xe8 pratico per servire le pagine nei tempi attuali. Alcuni trovano difficile accedere al server a causa di cloudflare."]}),"\n",(0,n.jsx)(i.h2,{id:"\xe8-colpa-mia-se-non-riesci-a-gestire-la-verit\xe0-2019",children:"\xc8 colpa mia se non riesci a gestire la verit\xe0? (2019)"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://agileotter.blogspot.com/2019/09/is-it-my-fault-you-cant-handle-truth.html",children:"Originale"}),".\nL'articolo mette in guardia dai pericoli di un'eccessiva razionalit\xe0, sottolineando che essere utili a volte \xe8 pi\xf9 importante che avere ragione. Spiega come gli individui eccessivamente razionali possano mancare di empatia e creare giochi di potere. L'articolo cita un esempio di approccio positivo alla risoluzione dei problemi e interroga i lettori sul fatto di nascondersi dietro la razionalit\xe0 per evitare le responsabilit\xe0. I commenti nella discussione di Hacker News includono argomenti come la produttivit\xe0 e la metodologia agile, dove gli utenti toccano la razionalit\xe0 e le disfunzioni aziendali. Un utente suggerisce un libro su Agile come riferimento. Non sono state menzionate nuove tecnologie o release."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35475482",children:"Discussion Service"}),".\nUn articolo sottolinea l'importanza di guidare piuttosto che di dire la verit\xe0 alle persone, poich\xe9 i fatti sono spesso inefficaci. Gli utenti di Discussion Service discutono dell'importanza dell'empatia e del contesto, sollevando dubbi sulla possibilit\xe0 di trarre piacere dalla rabbia. Gli esperti discutono sul bilanciamento tra onest\xe0 e gentilezza e sulla necessit\xe0 di empatia, rispetto e rigore scientifico. Il dibattito si concentra sullo scopo della scienza, sulla ricerca della verit\xe0 e sulla teoria dei giochi. Una comunicazione efficace della verit\xe0 richiede tatto, tempismo e costruzione di relazioni, perch\xe9 la negligenza porta alla crudelt\xe0 e alle lotte di potere. Alcuni sostengono che la verit\xe0 oggettiva in alcuni contesti pu\xf2 essere irrispettosa e che l'assunzione di una verit\xe0 \xe8 errata."]}),"\n",(0,n.jsx)(i.h2,{id:"corde-c-e-la-mia-lenta-discesa-verso-la-follia",children:"Corde C e la mia lenta discesa verso la follia"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://www.deusinmachina.net/p/c-strings-and-my-slow-descent-to",children:"Originale"}),".\nDiego Crespo parla della manipolazione delle stringhe in C e di funzioni comuni come strcpy e strlen, e dei potenziali problemi che derivano dal lavoro con queste funzioni. Le sfide del lavoro con i linguaggi non latini, in particolare con la codifica Unicode e UTF-8, sono descritte in dettaglio con possibili soluzioni. Viene sottolineata l'importanza della cautela nel lavorare con le stringhe in C, per evitare comportamenti non definiti e potenziali attacchi. Crespo osserva inoltre che il C++ evita alcuni di questi problemi trattando le stringhe come oggetti. I lettori sono invitati a consultare gli account dei social media e gli articoli dell'autore sui linguaggi di programmazione e sulla codifica di basso livello."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35467367",children:"Discussion Service"}),".\nGli utenti di Discussion Service discutono i problemi di sicurezza insiti nella gestione delle stringhe in C, suggeriscono di utilizzare librerie alternative e sottolineano la necessit\xe0 di una migliore gestione della memoria. La praticit\xe0 del C per l'elaborazione delle stringhe \xe8 discussa e alcuni raccomandano l'uso di allocatori o contenitori. Le librerie C predefinite vengono criticate per la loro inefficienza e gli utenti suggeriscono di rinominare la funzione strlen per migliorarne la leggibilit\xe0. I commenti riguardano anche i bug causati da strncpy() e le sfumature di Unicode. Gli entusiasti del C difendono l'accesso e il controllo del linguaggio, mentre altri lo trovano troppo complesso e discutono i diversi metodi di gestione delle stringhe in C. Vengono offerti consigli per evitare le comuni insidie della gestione delle stringhe in C. Si esprime frustrazione e si suggeriscono librerie di stringhe alternative agli array semplici. Nonostante la popolarit\xe0 del C, manca una soluzione efficiente per la gestione delle stringhe."]}),"\n",(0,n.jsx)(i.h2,{id:"mutexprotected-un-modello-c-per-una-concorrenza-pi\xf9-semplice",children:"MutexProtected: Un modello C++ per una concorrenza pi\xf9 semplice"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://awesomekling.github.io/MutexProtected-A-C++-Pattern-for-Easier-Concurrency/",children:"Originale"}),".\nL'articolo spiega le difficolt\xe0 di programmare applicazioni concorrenti utilizzando i lock e presenta un pattern C++ chiamato MutexProtected che semplifica questo processo. L'autore utilizza un esempio in C per dimostrare la necessit\xe0 di MutexProtected e prepara un esempio essenziale. L'articolo introduce poi una classe RAII in C++ per risolvere il problema dello sblocco dei mutex dimenticati, ma ne mostra i difetti. L'autore presenta poi MutexProtected come un potente costrutto che combina un mutex e un tipo di dati per garantire un corretto accesso concorrente ai dati. L'articolo si conclude con l'introduzione di MemoizedTreeMap, un'implementazione di una mappa ad albero che utilizza MutexProtected per garantire la sicurezza dei thread."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35464152",children:"Discussion Service"}),".\nMutexProtected \xe8 un pattern C++ per facilitare la concorrenza, come i mutex di Rust. Boost.synchronized \xe8 complesso, ma pu\xf2 essere usato solo come header. I commenti suggeriscono lambda e lock e unlock espliciti o in stile RAII, e scoped_lock per lock multipli. Gli esperti discutono su mutex e canali per la concorrenza."]}),"\n",(0,n.jsx)(i.h2,{id:"clarence-thomas-e-il-miliardario",children:"Clarence Thomas e il miliardario"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://www.propublica.org/article/clarence-thomas-scotus-undisclosed-luxury-travel-gifts-crow",children:"Originale"}),".\nProPublica riferisce che il giudice Clarence Thomas avrebbe accettato viaggi di lusso dal donatore repubblicano Harlan Crow per oltre due decenni, senza rivelarli nelle dichiarazioni finanziarie annuali, sollevando preoccupazioni etiche. Crow, che ha speso milioni per la politica conservatrice, possiede uno yacht e un jet privato su cui Thomas ha viaggiato e lo ha ospitato nel suo ranch in Texas e in un resort privato. L'accesso di Crow alla giustizia si estende a chiunque l'uomo d'affari scelga di invitare, violando potenzialmente le leggi sulla divulgazione. La guida etica aggiornata per i giudici chiarisce che la divulgazione \xe8 richiesta per tali soggiorni, compreso un viaggio del 2021 in un cimitero cattolico vicino a New York, dove \xe8 stata inaugurata una statua di bronzo dell'insegnante di terza media di Thomas, finanziata da Crow."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35467948",children:"Discussion Service"}),".\nUn giudice essenziale della Corte Suprema degli Stati Uniti potrebbe essere coinvolto in un'importante corruzione, in quanto potrebbe aver ricevuto favori illeciti da un miliardario; tuttavia, \xe8 improbabile che queste azioni portino a un impeachment nel clima ultra-politico di oggi. Anche se il giudice Thomas potrebbe non essere vincolato dalle regole etiche delle corti inferiori, potrebbero comunque essere intraprese azioni legali, tra cui un'indagine del Dipartimento di Giustizia o dell'IRS. L'evidente corruzione a livello giudiziario evidenzia l'influenza corruttrice dei super-ricchi sulle istituzioni governative, con un successo finora prevedibile. Nonostante siano palesemente contrarie alla legge, le azioni del giudice Thomas potrebbero non essere sanzionate, in parte a causa del rifiuto di chiedere conto a chi detiene il potere."]}),"\n",(0,n.jsx)(i.h2,{id:"la-scarsa-componibilit\xe0-di-rust",children:"La scarsa componibilit\xe0 di Rust"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://thedav.is/post/rusts-poor-composability/",children:"Originale"}),".\nL'autore discute la scarsa componibilit\xe0 di Rust, evidenziando i problemi di sintassi con i cicli for e gli iteratori e il modo in cui ci\xf2 influisce sui casi d'uso reali; l'autore critica la mancanza di flessibilit\xe0 e componibilit\xe0 di Rust, sostenendo la necessit\xe0 di un rallentamento dello sviluppo del linguaggio per concentrarsi sull'ergonomia; l'autore cita il lavoro in corso sulle parole chiave generiche e sui riferimenti per migliorare la componibilit\xe0."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35468168",children:"Discussion Service"}),".\nGli utenti discutono sulla componibilit\xe0 di Rust: alcuni ne lodano la versatilit\xe0, altri ne criticano l'inflessibilit\xe0 con gli iteratori. La potenza e il sistema di tipi di Rust sono ammirati, ma alcuni trovano la sua sintassi ingombrante. I team dovrebbero concentrarsi sull'ergonomia, anche se alcuni suggeriscono di usare altri linguaggi se Rust non piace. Il thread Discussion Service discute le insidie della programmazione di Rust, le chiusure e il modello iterativo. Vengono criticati la sintassi di Rust, il sistema di effetti e i limiti delle chiusure. Problemi di componibilit\xe0 sorgono con le chiusure asincrone di Rust e il supporto al lifetime. Rust sperimenta il codice generico su sync+async, mentre Goroutines e Zig hanno questa caratteristica."]}),"\n",(0,n.jsx)(i.h2,{id:"individuare-ed-evitare-la-frammentazione-dellheap-nelle-applicazioni-rust",children:"Individuare ed evitare la frammentazione dell'heap nelle applicazioni Rust"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://www.svix.com/blog/heap-fragmentation-in-rust-applications/",children:"Originale"}),".\nUn progetto Rust si \xe8 trovato di fronte a una crescita illimitata della memoria probabilmente causata dalla frammentazione dell'heap, risolta sostituendo l'allocatore con jemalloc per ottenere un profilo di memoria migliore. Un benchmark.yml nel repo del progetto testa diversi input. Svix cerca esperti di Rust per un servizio scalabile per la sua comunit\xe0."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35469632",children:"Discussion Service"}),".\nUn articolo parla di come evitare la frammentazione dell'heap nelle applicazioni Rust e suggerisce che jemalloc pu\xf2 aiutare. I commenti suggeriscono di compattare l'heap, gli handle, tcmalloc. Vengono discusse le opzioni e i compromessi per la scelta dell'heap. Vengono presi in considerazione il marketing dei progetti open source e l'individuazione della frammentazione dell'heap. jemalloc \xe8 consigliato per l'elevato utilizzo di memoria di un server HTTP a causa dell'allocazione a blocchi di Rust. Si apprezza l'efficienza del sistema di tipi di Rust, con un SLA del 99,999% ottenuto grazie a test e ridondanze."]}),"\n",(0,n.jsx)(i.h2,{id:"fate-attenzione-a-ci\xf2-che-testate-o-distribuite-su-vercel",children:"Fate attenzione a ci\xf2 che testate o distribuite su Vercel."}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://twitter.com/shoeboxdnb/status/1643639119824801793",children:"Original"}),".\nL'articolo avverte di essere cauti nel testare o distribuire su Vercel, perch\xe9 potrebbe risultare un IP nella lista nera. Gli utenti raccontano le loro esperienze personali con il divieto di utilizzo dell'IP di Vercel, citando i problemi di produttivit\xe0 e comunicazione del loro team. Alcuni suggeriscono che il divieto possa essere legato ai tentativi errati di Vercel di prevenire gli abusi. Le soluzioni includono il contatto con l'assistenza clienti o il passaggio a un altro servizio. Un commento di Discussion Service sottolinea l'importanza della sicurezza dell'infrastruttura cloud e dei test adeguati."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35474837",children:"Discussion Service"}),".\nVercel risolve i problemi di fatturazione, esplora i limiti di utilizzo. Alcuni criticano il processo di rimborso. L'ottimizzazione dei costi del cloud \xe8 importante. Vercel viene confrontato con AWS App Runner e altre alternative pi\xf9 economiche. Serverless pu\xf2 portare a fatturazioni inaspettate."]}),"\n",(0,n.jsx)(i.h2,{id:"linux-64-porta-le-aggiunte-di-apple-m2-per-i-macbook-e-i-mac-mini-2022",children:"Linux 6.4 porta le aggiunte di Apple M2 per i MacBook e i Mac Mini 2022"}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://www.phoronix.com/news/Apple-M2-Device-Tree-Linux-6.4",children:"Originale"}),".\nLe aggiunte del Device Tree (DT) per i dispositivi M2 di Apple, inclusi MacBook Air, MacBook Pro e Mac Mini, saranno aggiunte a Linux 6.4. Hector Martin, sviluppatore principale di Asahi Linux, ha presentato gli aggiornamenti del DT per i SoC Apple per l'accodamento nell'albero dei SoC prima dell'apertura della finestra di fusione alla fine del mese. L'aggiunta della serie Apple M2 Device Tree e del supporto per l'hardware essenziale delle macchine sul DT porter\xe0 il necessario supporto upstream del kernel per Apple M2. Tuttavia, il dispositivo non \xe8 ancora utilizzabile dagli utenti finali e chi desidera la migliore esperienza Linux per Apple M1/M2 dovr\xe0 utilizzare una distribuzione downstream come Asahi Linux."]}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35470392",children:"Discussion Service"}),".\nLinux 6.4 aggiunge il supporto per Apple M2 per i MacBook/Mac Mini del 2022. Gli utenti di Discussion Service confrontano la gestione energetica di Linux/MacOS. Asahi Linux non \xe8 ancora una soluzione perfetta. Eccitazione ma frustrazione per la qualit\xe0 dei commenti. Gli utenti lamentano disinformazione e sciocchezze. La qualit\xe0 della discussione \xe8 peggiorata in un particolare dominio. Un utente suggerisce di bloccarlo. Il resto della discussione non sembra influenzato."]}),"\n",(0,n.jsx)(i.h2,{id:"illustrazioni-di-treni-di-manutenzione-giapponesi-invisibili-che-funzionano-solo-di-notte",children:'Illustrazioni di treni di manutenzione giapponesi "invisibili" che funzionano solo di notte'}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"https://www.spoon-tamago.com/toei-project-unseen-maintenance-trains/",children:"Originale"}),'.\nL\'artista Masami Onishi ha illustrato la raramente vista forza lavoro giapponese dei treni notturni che eseguono lavori di manutenzione sui binari e sui cavi elettrici durante le prime ore del mattino, garantendo cos\xec un servizio regolare e ininterrotto per tutto il giorno. Le illustrazioni dettagliate di questi treni fanno parte del Progetto Toei del Tokyo Metropolitan Bureau of Transportation. Tra questi, la "Carrozza per la levigatura delle rotaie", che leviga le abrasioni sulle rotaie, e la "Carrozza per l\'ispezione elettrica", che valuta l\'altezza, la tensione e le condizioni delle linee elettriche aeree. Le ferrovie giapponesi hanno un tasso notevolmente basso di deragliamenti, con solo due incidenti di questo tipo registrati in tutto il Paese nel 2018.']}),"\n",(0,n.jsxs)(i.p,{children:[(0,n.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35474895",children:"Discussion Service"}),".\nIllustrazioni dei treni di manutenzione giapponesi \"non visti\" che lavorano solo di notte, evidenziate dal Progetto Toei. Gli abitanti di New York commentano l'inadeguatezza della manutenzione della metropolitana 24 ore su 24, 7 giorni su 7, alcuni dando la colpa a professioni obsolete come gli operatori delle porte. Il contrasto tra i vagoni puliti della metropolitana di Tokyo e la scarsa manutenzione di New York porta alla discussione sulle infrastrutture carenti di altre citt\xe0 americane. Le ferrovie giapponesi beneficiano di investitori privati e finanziamenti statali, in contrasto con la perdita del trasporto pubblico americano, considerato un bene pubblico. Il governo metropolitano di Tokyo possiede molti treni, mantenuti attraverso sofisticati sistemi di intelligenza artificiale, con l'intenzione di renderli completamente autonomi entro il 2032. Nelle ore di punta Tokyo \xe8 meno scomoda di Londra o New York, grazie ai posti riservati."]})]})}function u(e={}){const{wrapper:i}={...(0,t.R)(),...e.components};return i?(0,n.jsx)(i,{...e,children:(0,n.jsx)(d,{...e})}):d(e)}}}]);